def best_circular_selection(values, k):
    n = len(values)
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return 0
    if n == 1:
        if k == 1:
            return int(values[0])
        raise ValueError("no valid selection")
    if k > n // 2:
        raise ValueError("no valid selection")

    NEG = float('-inf')

    def path_best(arr, m):
        """Max sum of exactly m pairwise non-adjacent elements of a path arr.
        Returns NEG if impossible."""
        if m == 0:
            return 0
        if m < 0 or m > (len(arr) + 1) // 2:
            return NEG
        # prev2 = f[i-2], prev1 = f[i-1]; index j = count chosen (0..m)
        prev2 = [0] + [NEG] * m   # f[-1]: only j=0 feasible
        prev1 = [0] + [NEG] * m   # f[0]:  empty prefix
        for v in arr:
            shifted = [NEG] + prev2[:-1]          # f[i-2][j-1]
            cur = [a if a >= b + v else b + v
                   for a, b in zip(prev1, shifted)]
            prev2, prev1 = prev1, cur
        return prev1[m]

    # Case A: index 0 not chosen -> path values[1:]
    best = path_best(values[1:], k)

    # Case B: index 0 chosen -> indices 1 and n-1 excluded
    sub = path_best(values[2:n - 1], k - 1)
    if sub != NEG:
        cand = values[0] + sub
        if cand > best:
            best = cand

    if best == NEG:
        raise ValueError("no valid selection")
    return int(best)

from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    N = R * C
    flat = [v for row in grid for v in row]
    INF = float('inf')

    def bfs(src):
        dist = [-1] * N
        dist[src] = 0
        dq = deque([src])
        while dq:
            u = dq.popleft()
            d = dist[u] + 1
            r, col = divmod(u, C)
            if r > 0:
                v = u - C
                if dist[v] < 0 and flat[v] != -1:
                    dist[v] = d; dq.append(v)
            if r < R - 1:
                v = u + C
                if dist[v] < 0 and flat[v] != -1:
                    dist[v] = d; dq.append(v)
            if col > 0:
                v = u - 1
                if dist[v] < 0 and flat[v] != -1:
                    dist[v] = d; dq.append(v)
            if col < C - 1:
                v = u + 1
                if dist[v] < 0 and flat[v] != -1:
                    dist[v] = d; dq.append(v)
        return dist

    start, end = 0, N - 1
    ds = bfs(start)
    dt = bfs(end)

    best = ds[end] if ds[end] >= 0 else INF

    # Per label: minimum distance from start, minimum distance to end
    min_s = {}
    min_t = {}
    for i in range(N):
        lab = flat[i]
        if lab == -1:
            continue
        a = ds[i]
        if a >= 0:
            cur = min_s.get(lab)
            if cur is None or a < cur:
                min_s[lab] = a
        b = dt[i]
        if b >= 0:
            cur = min_t.get(lab)
            if cur is None or b < cur:
                min_t[lab] = b

    for lab, a in min_s.items():
        b = min_t.get(lab)
        if b is not None:
            total = a + c + b
            if total < best:
                best = total

    return -1 if best == INF else best

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("no balanced replacement exists")
    opens = s.count('(')
    q = s.count('?')
    need = n // 2 - opens
    if need < 0 or need > q:
        raise ValueError("no balanced replacement exists")

    res = []
    bal = 0
    for c in s:
        if c == '?':
            if need > 0:
                c = '('
                need -= 1
            else:
                c = ')'
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError("no balanced replacement exists")
        res.append(c)
    if bal != 0:
        raise ValueError("no balanced replacement exists")
    return ''.join(res)

def resolve_build_order(deps):
    # Build adjacency: every package (keys and dependency-only names) gets an entry.
    # Use sets so duplicate dependency entries count once.
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()   # nodes on the current DFS path
    done = set()       # nodes already emitted into `order`

    for root in sorted(graph):
        if root in done:
            continue
        visiting.add(root)
        stack = [(root, iter(sorted(graph[root])))]
        while stack:
            node, children = stack[-1]
            for dep in children:
                if dep in done:
                    continue                      # shared dependency, already built
                if dep in visiting:
                    raise ValueError("dependency cycle detected at " + dep)
                visiting.add(dep)
                stack.append((dep, iter(sorted(graph[dep]))))
                break
            else:
                # All dependencies of `node` are finished.
                stack.pop()
                visiting.discard(node)
                done.add(node)
                order.append(node)
    return order

import re

_AMOUNT_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("amount must be a string")
        m = _AMOUNT_RE.fullmatch(amount)
        if m is None:
            raise ValueError(f"invalid amount: {amount!r}")
        whole, frac = m.group(1), m.group(2) or ""
        cents = int(whole) * 100 + int(frac.ljust(2, "0"))
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def apply_hunks(lines, hunks):
    n = len(lines)
    for start, delete, insert in hunks:
        if start < 0 or delete < 0 or start + delete > n:
            raise ValueError("hunk out of range")

    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev_start, prev_delete, _ = ordered[i - 1]
        cur_start = ordered[i][0]
        if cur_start == prev_start or cur_start < prev_start + prev_delete:
            raise ValueError("conflicting hunks")

    result = []
    pos = 0  # current position in the ORIGINAL document
    for start, delete, insert in ordered:
        result.extend(lines[pos:start])   # untouched lines before this hunk
        result.extend(insert)             # replacement lines
        pos = start + delete              # skip the deleted original lines
    result.extend(lines[pos:])            # untouched tail
    return result

import copy


def merge_settings(defaults, overrides):
    result = copy.deepcopy(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = copy.deepcopy(value)
    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        # Prune admitted calls that have expired: s expires at t when t - s >= window.
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        # Admit only if strictly fewer than max_calls admitted calls remain in the window.
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

