class TaskScheduler:
    """Priority queue of unique task ids with reprioritization and cancellation.

    Higher priority is served first; ties are served in FIFO order of the
    task's original submission (reprioritizing does not change FIFO position).
    """

    _COMPACT_MIN = 64  # don't bother compacting tiny heaps

    def __init__(self):
        self._heap = []                 # entries: (-priority, seq, token, task_id)
        self._active = {}               # task_id -> (priority, seq, token)
        self._seq = count()             # FIFO position, assigned at submission
        self._token = count()           # unique per heap entry

    # ------------------------------------------------------------------ #
    # internal helpers
    # ------------------------------------------------------------------ #
    def _push(self, task_id, priority, seq):
        token = next(self._token)
        self._active[task_id] = (priority, seq, token)
        heapq.heappush(self._heap, (-priority, seq, token, task_id))
        self._maybe_compact()

    def _is_live(self, entry):
        _, _, token, task_id = entry
        info = self._active.get(task_id)
        return info is not None and info[2] == token

    def _discard_stale_top(self):
        heap = self._heap
        while heap and not self._is_live(heap[0]):
            heapq.heappop(heap)

    def _maybe_compact(self):
        heap = self._heap
        if len(heap) > self._COMPACT_MIN and len(heap) > 2 * len(self._active):
            self._heap = [e for e in heap if self._is_live(e)]
            heapq.heapify(self._heap)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #
    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task {task_id!r} is already active")
        self._push(task_id, priority, next(self._seq))

    def reprioritize(self, task_id, priority):
        info = self._active.get(task_id)
        if info is None:
            raise KeyError(task_id)
        _, seq, _ = info
        # New token invalidates every older heap entry for this task.
        self._push(task_id, priority, seq)

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]       # its heap entries are now stale
        self._maybe_compact()

    def pop(self):
        self._discard_stale_top()
        if not self._heap:
            raise IndexError("pop from empty TaskScheduler")
        _, _, _, task_id = heapq.heappop(self._heap)
        del self._active[task_id]
        return task_id

    def peek(self):
        self._discard_stale_top()
        if not self._heap:
            raise IndexError("peek from empty TaskScheduler")
        return self._heap[0][3]

    def priority_of(self, task_id):
        info = self._active.get(task_id)
        if info is None:
            raise KeyError(task_id)
        return info[0]

    def __len__(self):
        return len(self._active)

class UndoStack:
    """A LIFO stack whose successful push/pop operations can be undone.

    Every successful push or pop adds one entry to the history. Each call to
    undo() removes the newest entry and reverses it. Because entries are
    always undone newest-first, the stack is back in the exact state it had
    right after the operation being undone. So undoing a push only needs to
    remove the top item, and undoing a pop only needs to put the popped
    value back on top.
    """

    _PUSH = 0
    _POP = 1

    def __init__(self):
        self._items = []
        self._history = []  # entries: (_PUSH, None) or (_POP, value)

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append((self._PUSH, None))

    def pop(self):
        if not self._items:
            # Failed pop: the history is left untouched.
            raise IndexError("pop from empty UndoStack")
        value = self._items.pop()
        self._history.append((self._POP, value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty UndoStack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        kind, value = self._history.pop()
        if kind == self._PUSH:
            # The pushed value is guaranteed to be on top.
            self._items.pop()
        else:
            # Restore the exact popped object.
            self._items.append(value)

    def __len__(self) -> int:
        return len(self._items)

def kth_root_floor(n: int, k: int) -> int:
    if isinstance(n, bool) or isinstance(k, bool) or not isinstance(n, int) or not isinstance(k, int):
        raise TypeError("n and k must be integers")
    if n < 0:
        raise ValueError("n must be nonnegative")
    if k < 1:
        raise ValueError("k must be >= 1")

    if n < 2 or k == 1:
        return n

    bits = n.bit_length()
    if k >= bits:
        # n < 2**bits <= 2**k, so the root is 1 (n >= 2 here)
        return 1

    # Initial guess strictly >= the true root: 2**ceil(bits/k)
    x = 1 << ((bits + k - 1) // k)
    while True:
        y = ((k - 1) * x + n // (x ** (k - 1))) // k
        if y >= x:
            break
        x = y

    # Safety check (Newton from above guarantees this, but verify cheaply)
    while x ** k > n:
        x -= 1
    while (x + 1) ** k <= n:
        x += 1
    return x

import math


def vector_norm(v: list[float]) -> float:
    """Euclidean (L2) norm of v, robust across the full double-precision range."""
    # Validate and convert entries.
    xs = []
    for x in v:
        try:
            fx = float(x)
        except OverflowError:
            raise ValueError(f"entry too large to represent as float: {x!r}")
        if math.isnan(fx) or math.isinf(fx):
            raise ValueError(f"non-finite entry in vector: {x!r}")
        xs.append(abs(fx))

    if not xs:
        return 0.0

    m = max(xs)
    if m == 0.0:
        return 0.0

    # m = f * 2**e with 0.5 <= f < 1, so x * 2**-e lies in [0, 1) for every x.
    # Scaling by an exact power of two introduces no rounding error, except
    # for entries so small relative to m that they may lose low bits. Such
    # entries contribute nothing measurable to the norm anyway.
    # math.ldexp(x, -e) scales each element directly. This avoids forming
    # 2**-e on its own, which could overflow when m is subnormal.
    _, e = math.frexp(m)
    s = math.fsum(math.ldexp(x, -e) ** 2 for x in xs)  # accurate summation

    r = math.sqrt(s)  # r lies in [0.5, sqrt(n)]
    try:
        return math.ldexp(r, e)
    except OverflowError:
        # The true norm exceeds the largest finite double: not representable.
        return math.inf

import heapq


def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0

    heap: list[int] = []          # min-heap of selected bounties
    push = heapq.heappush
    replace = heapq.heapreplace
    size = 0

    for d, p in sorted(jobs):     # ascending deadline
        if size < cap * d:
            push(heap, p)
            size += 1
        elif heap[0] < p:
            # Slots up to d are full: swap out the cheapest selected job.
            replace(heap, p)

    return sum(heap)

from collections import Counter

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError("m must be >= 1")
    if not values:
        return 0

    # Combined key: residue * 2 + parity (both non-negative for m >= 1).
    counts = Counter([(v % m) * 2 + (v & 1) for v in values])

    total = 0
    for key, n in counts.items():
        r, p = key >> 1, key & 1
        c = (-r) % m
        if c == r:
            total += n * (n - 1) // 2
        elif r < c:
            other = counts.get(c * 2 + p)
            if other:
                total += n * other
    return total

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(data)
    q = len(queries)
    ans = [0] * q
    if n == 0 or q == 0:
        return ans

    # prev[i] = index of previous occurrence of data[i], or -1
    prev = [-1] * n
    last = {}
    for i, v in enumerate(data):
        prev[i] = last.get(v, -1)
        last[v] = i

    # Bucket queries by right endpoint
    by_r = [None] * (n + 1)
    for qi, (l, r) in enumerate(queries):
        if l >= r:
            continue  # empty slice -> 0 (already set)
        b = by_r[r]
        if b is None:
            by_r[r] = [(l, qi)]
        else:
            b.append((l, qi))

    tree = [0] * (n + 1)  # Fenwick tree, 1-indexed
    total = 0

    for i in range(n):
        p1 = prev[i]
        if p1 >= 0:
            # add mark at p1
            j = p1 + 1
            while j <= n:
                tree[j] += 1
                j += j & (-j)
            total += 1
            p2 = prev[p1]
            if p2 >= 0:
                # remove mark at p2
                j = p2 + 1
                while j <= n:
                    tree[j] -= 1
                    j += j & (-j)
                total -= 1

        b = by_r[i + 1]
        if b is not None:
            for l, qi in b:
                # count marks at positions 0..l-1
                s = 0
                j = l
                while j > 0:
                    s += tree[j]
                    j &= j - 1
                ans[qi] = total - s

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}

    for i, row in enumerate(rows):
        # a. structure check
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(
                "row {}: expected a tuple of exactly 3 elements".format(i)
            )

        category, amount, refunded = row

        # b. category check
        if not isinstance(category, str) or category == "":
            raise ValueError(
                "row {}: category must be a non-empty str".format(i)
            )

        # c. amount type check (bool explicitly rejected)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(
                "row {}: amount must be an int or float (not bool)".format(i)
            )

        # d. amount range check
        if amount < 0:
            raise ValueError(
                "row {}: amount must be >= 0".format(i)
            )

        # e. refunded type check
        if not isinstance(refunded, bool):
            raise TypeError(
                "row {}: refunded must be a bool".format(i)
            )

        value = float(amount)

        summary = result.get(category)
        if summary is None:
            summary = {"count": 0, "gross": 0.0, "net": 0.0, "largest": value}
            result[category] = summary

        summary["count"] += 1
        summary["gross"] += value
        if not refunded:
            summary["net"] += value
        if value > summary["largest"]:
            summary["largest"] = value

    return result

def clamp_values(values, low, high):
    # Rule 1: the container must be a list
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    # Rule 2: bounds must be real numbers, and bool is rejected explicitly
    def _is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    if not _is_number(low) or not _is_number(high):
        raise TypeError("bounds must be numbers")

    # Rule 3: the bounds must be ordered
    if low > high:
        raise ValueError("low must not exceed high")

    # Rule 4: check every element before building any output
    for i, item in enumerate(values):
        if not _is_number(item):
            raise TypeError(
                "element at index {} is not a number: {!r}".format(i, item)
            )

    # Build a fresh list. The input is never mutated.
    result = []
    for item in values:
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)  # keep the original object
    return result

def flatten_depth(nested, max_depth):
    # Validation, checked in the required order
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Explicit stack of (iterator over a list, depth of that list's elements).
    # Elements of `nested` itself are at depth 0; a list element found at
    # depth d is expanded only if d < max_depth.
    stack = [(iter(nested), 0)]

    while stack:
        it, depth = stack[-1]
        for item in it:
            if isinstance(item, list) and depth < max_depth:
                # Descend into the sublist; resume this iterator later.
                stack.append((iter(item), depth + 1))
                break
            result.append(item)  # atoms (and unexpanded lists) by reference
        else:
            # Iterator exhausted: this list is done.
            stack.pop()

    return result

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = set(
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789_"
    )

    out = []
    n = len(template)
    i = 0
    while i < n:
        ch = template[i]
        if ch == "{":
            # Escape detection wins: "{{" is a literal "{".
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            # Opening "{" of a placeholder.
            start = i
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError(
                        "unclosed placeholder at position %d" % start
                    )
                c = template[j]
                if c == "}":
                    break
                if c not in name_chars:
                    raise ValueError(
                        "invalid placeholder at position %d" % start
                    )
                j += 1
            name = template[start + 1:j]
            if not name:
                raise ValueError("empty placeholder at position %d" % start)
            try:
                value = context[name]
            except KeyError:
                raise KeyError(name) from None
            out.append(str(value))
            i = j + 1
        elif ch == "}":
            # "}}" is a literal "}".
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
                continue
            raise ValueError("stray '}' at position %d" % i)
        else:
            out.append(ch)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    DIGITS = "0123456789"
    OPERATORS = ("+", "-", "*", "/")

    def digits_to_int(s):
        # Convert an ASCII digit string to int without hitting the
        # int(str) max-digits limit on newer Python versions.
        if len(s) <= 1000:
            return int(s)
        mid = len(s) // 2
        return digits_to_int(s[:mid]) * (10 ** (len(s) - mid)) + digits_to_int(s[mid:])

    def parse_literal(tok):
        # Returns int value or None if tok is not a valid literal.
        body = tok
        negative = False
        if body[:1] in ("+", "-"):
            negative = body[0] == "-"
            body = body[1:]
        if not body:
            return None
        for ch in body:
            if ch not in DIGITS:
                return None
        value = digits_to_int(body)
        return -value if negative else value

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError("token %d is not a str: %r" % (i, tok))

        if tok in OPERATORS:
            if len(stack) < 2:
                raise ValueError("stack underflow at token %d" % i)
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token %d" % i)
                stack.append(trunc_div(left, right))
        else:
            value = parse_literal(tok)
            if value is None:
                raise ValueError("unknown token %r at token %d" % (tok, i))
            stack.append(value)

    if len(stack) > 1:
        raise ValueError("leftover operands: %d values remain on the stack" % len(stack))
    return stack[0]

def deep_get(data, path):
    """Navigate `data` along a dot-separated `path` and return the value found.

    Each segment is used as a dict key when the current node is a dict,
    or as an integer index when it is a list (negative indices allowed).
    """
    if not isinstance(path, str):
        raise TypeError("path must be a string, got %s" % type(path).__name__)
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    # Reject empty segments before any navigation happens.
    if "" in segments:
        raise ValueError("empty segment in path %r" % (path,))

    return _walk(data, segments, 0)


def _is_int_literal(seg):
    """True if seg is an optional single '-' followed by one or more ASCII digits."""
    body = seg[1:] if seg.startswith("-") else seg
    # isascii() rules out non-ASCII digits such as "²" or "٣".
    return body != "" and body.isascii() and body.isdigit()


def _walk(node, segments, i):
    """Recursive traversal: consume segments[i:] starting at node."""
    if i == len(segments):
        return node

    seg = segments[i]

    if isinstance(node, dict):
        if seg not in node:
            raise KeyError(seg)
        return _walk(node[seg], segments, i + 1)

    if isinstance(node, list):
        if not _is_int_literal(seg):
            raise ValueError("invalid index %r for list" % (seg,))
        idx = int(seg)
        if idx >= len(node) or idx < -len(node):
            raise IndexError("list index %s out of range" % seg)
        return _walk(node[idx], segments, i + 1)

    raise TypeError(
        "cannot descend into %s with segment %r" % (type(node).__name__, seg)
    )

def top_k_frequent(items, k):
    # Validation, in the required order
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    # Count occurrences and remember the order of first appearance.
    # `items` is only read, never modified.
    counts = {}
    first_seen = []
    for x in items:
        if x in counts:
            counts[x] += 1
        else:
            counts[x] = 1
            first_seen.append(x)

    pairs = [(v, counts[v]) for v in first_seen]
    n = len(pairs)
    limit = k if k < n else n

    # Repeated selection: each round picks the unused pair with the highest
    # count. The comparison is strict (>), so for equal counts the pair that
    # appeared first in `items` (lowest index) wins.
    used = [False] * n
    result = []
    for _ in range(limit):
        best = -1
        for i in range(n):
            if used[i]:
                continue
            if best == -1 or pairs[i][1] > pairs[best][1]:
                best = i
        used[best] = True
        result.append(pairs[best])

    return result
